 "content": "from collections import Counter


def transform(grid):
    """Copy the rare nonzero template into every all-zero placement."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    background = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != background)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0 = min(r for r, _ in points)
    c0 = min(c for _, c in points)
    shape = {(r - r0, c - c0) for r, c in points}
    sh = max(r for r, _ in shape) + 1
    sw = max(c for _, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(h - sh + 1):
        for c in range(w - sw + 1):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r + dr][c + dc] = marker
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
